{"implementation":{"kind":"python","body":"import difflib

def solve(inputs):
    suggestions = []
    for diag in inputs.get('diagnostics', []):
        if diag.get('code') == 'unknown_goal':
            message = diag.get('message', '')
            missing_symbol = message.rsplit(':', 1)[-1].strip()
            known_goals = inputs.get('known_goals', [])
            matches = difflib.get_close_matches(missing_symbol, known_goals, n=1, cutoff=0.6)
            if matches:
                suggestions.append({'code': 'unknown_goal', 'replacement': matches[0]})
    return {'suggestions': suggestions}
"},"clarification":""}
